"use client";

import { useState } from "react";
import CollectionsPane from "./CollectionsPane";
import { handleImportCurl } from "./importCurl";
import * as buildCurl from "./buildCurl";
import * as util from "../api-playground/util";
import * as constants from "./util";
import { executeApiRequest } from "../components/springApiCalls";
import styles from "./apiPlayground.module.css";

export default function ApiPlaygroundPage() {
    const [method, setMethod] = useState(constants.DEFAULT_REQUEST_METHOD);
    const [url, setUrl] = useState("");
    const [paramsRows, setParamsRows] = useState([]);
    const [headerRows, setHeaderRows] = useState([{ ...constants.DEFAULT_HEADER_ROW }]);
    const [bodyInput, setBodyInput] = useState(constants.DEFAULT_BODY_INPUT);
    const [activeTab, setActiveTab] = useState(constants.DEFAULT_ACTIVE_TAB);
    const [importCurlText, setImportCurlText] = useState("");
    const [importMessage, setImportMessage] = useState("");
    const [copyMessage, setCopyMessage] = useState("");
    const [showSuccessToast, setShowSuccessToast] = useState(false);
    const [responsePreview, setResponsePreview] = useState(constants.RESPONSE_PREVIEW_TEXT);
    const canSendBody = method !== "GET" && method !== "DELETE";

    const updateRow = (setter, rowIndex, field, fieldValue) => {
        setter((prev) => prev.map((row, index) => (index === rowIndex ? { ...row, [field]: fieldValue } : row)));
    };

    const addRow = (setter) => {
        setter((prev) => [...prev, util.createEmptyRow()]);
    };

    const removeRow = (setter, rowIndex) => {
        setter((prev) => prev.filter((_, index) => index !== rowIndex));
    };

    const { requestUrlPreview } = buildCurl.buildRequestUrlPreview({ paramsRows, url });

    const { curlCommand } = buildCurl.buildCurlParts({
        headerRows,
        canSendBody,
        bodyInput,
        method,
        requestUrlPreview,
    });

    const onImportCurlClick = () => {
        handleImportCurl({
            importCurlText,
            setUrl,
            setParamsRows,
            setHeaderRows,
            setBodyInput,
            setMethod,
            setImportCurlText,
            setImportMessage,
            setShowSuccessToast,
            setActiveTab,
        });
    };

    const onCopyCurlClick = () => {
        buildCurl.onCopyCurlClick({ curlCommand, setCopyMessage });
    }

    const onNewClick = () => {
        setMethod(constants.DEFAULT_REQUEST_METHOD);
        setUrl("");
        setParamsRows([]);
        setHeaderRows([{ ...constants.DEFAULT_HEADER_ROW }]);
        setBodyInput(constants.DEFAULT_BODY_INPUT);
        setImportCurlText("");
        setImportMessage("");
        setCopyMessage("");
        setShowSuccessToast(false);
        setActiveTab(constants.DEFAULT_ACTIVE_TAB);
    };

    // Utility to build JSON request for /api/execute
    function buildApiExecuteJson() {
        // Build headers map from enabled headerRows
        const headers = {};
        headerRows.forEach(row => {
            if (row.enabled && row.key && row.value) {
                headers[row.key] = row.value;
            }
        });
        // Build queryParams map from enabled paramsRows
        const queryParams = {};
        paramsRows.forEach(row => {
            if (row.enabled && row.key && row.value) {
                queryParams[row.key] = row.value;
            }
        });
        // Parse bodyInput as JSON if possible, else send as string
        let body = null;
        if (bodyInput && bodyInput.trim() !== "" && bodyInput.trim() !== "{}") {
            try {
                body = JSON.parse(bodyInput);
            } catch {
                body = bodyInput;
            }
        }
        return {
            method,
            url,
            headers,
            queryParams,
            body
        };
    }

    // Handler for Send button
    async function onSendClick() {
        setResponsePreview("{\"message\": \"Loading...\"}");
        try {
            const requestJson = buildApiExecuteJson();
            const response = await executeApiRequest(requestJson);
            setResponsePreview(JSON.stringify(response, null, 2));
        } catch (err) {
            setResponsePreview(JSON.stringify({ error: err.message }, null, 2));
        }
    }

    return (
        <main className={styles.main} style={{ fontFamily: constants.APP_FONT }}>
            {showSuccessToast && (
                <div className={styles.toast}>
                    Imported cURL successfully.
                </div>
            )}

            <div className={styles.layout}>
                <CollectionsPane />

                <section className={styles.section}>

                    <div className={styles.requestRow}>
                        <select
                            value={method}
                            onChange={(e) => setMethod(e.target.value)}
                            className={styles.methodSelect}
                        >
                            {constants.HTTP_METHODS.map((httpMethod) => (
                                <option key={httpMethod} value={httpMethod}>
                                    {httpMethod}
                                </option>
                            ))}
                        </select>

                        <input
                            value={url}
                            onChange={(e) => setUrl(e.target.value)}
                            placeholder="Enter request URL"
                            className={styles.urlInput}
                        />
                        <button
                            type="button"
                            onClick={onSendClick}
                            className={styles.primaryBtn}
                        >Send</button>
                        <button
                            type="button"
                            onClick={onNewClick}
                            className={styles.primaryBtn}
                        >Cancel</button>

                    </div>

                    <div className={styles.requestUrlPreview}>
                        Request URL: {requestUrlPreview}
                    </div>

                    <div className={styles.tabsRow}>
                        {constants.REQUEST_TABS.map((tab) => {
                            const isActive = activeTab === tab;

                            return (
                                <button
                                    key={tab}
                                    type="button"
                                    onClick={() => setActiveTab(tab)}
                                    className={`${styles.tabButton} ${isActive ? styles.tabButtonActive : styles.tabButtonInactive}`}
                                >
                                    {tab}
                                </button>
                            );
                        })}

                        <div className={styles.rightActions}>
                            <button
                                type="button"
                                onClick={onNewClick}
                                className={styles.secondaryBtn}
                            >
                                New
                            </button>
                            <button
                                type="button"
                                onClick={onNewClick}
                                className={styles.secondaryBtn}
                            >
                                Save to Collection
                            </button>
                        </div>
                    </div>

                    {activeTab === "Params" && (
                        <div className={styles.tabPanel}>
                            <div className={styles.dataCard}>
                                <div className={styles.tableHeaderRow} style={{ gridTemplateColumns: constants.TABLE_COLUMNS }}>
                                    <div className={styles.tableHeaderCell}>On</div>
                                    <div className={styles.tableHeaderCell}>Key</div>
                                    <div className={styles.tableHeaderCell}>Value</div>
                                    <div className={styles.tableHeaderCell}>Description</div>
                                    <div className={styles.tableHeaderCell} />
                                </div>

                                <div className={styles.tableBody}>
                                    {paramsRows.map((row, rowIndex) => (
                                        <div key={`param-${rowIndex}`} className={styles.tableDataRow} style={{ gridTemplateColumns: constants.TABLE_COLUMNS }}>
                                            <div className={styles.tableCellPad}>
                                                <input
                                                    type="checkbox"
                                                    checked={row.enabled}
                                                    onChange={(e) => updateRow(setParamsRows, rowIndex, "enabled", e.target.checked)}
                                                />
                                            </div>
                                            <input
                                                value={row.key}
                                                onChange={(e) => updateRow(setParamsRows, rowIndex, "key", e.target.value)}
                                                className={styles.tableInput}
                                            />
                                            <input
                                                value={row.value}
                                                onChange={(e) => updateRow(setParamsRows, rowIndex, "value", e.target.value)}
                                                className={styles.tableInput}
                                            />
                                            <input
                                                value={row.description}
                                                onChange={(e) => updateRow(setParamsRows, rowIndex, "description", e.target.value)}
                                                className={styles.tableInput}
                                            />
                                            <button
                                                type="button"
                                                onClick={() => removeRow(setParamsRows, rowIndex)}
                                                className={styles.iconBtn}
                                            >
                                                x
                                            </button>
                                        </div>
                                    ))}
                                </div>

                                <button
                                    type="button"
                                    onClick={() => addRow(setParamsRows)}
                                    className={styles.addRowBtn}
                                >
                                    + Add Param
                                </button>
                            </div>
                        </div>
                    )}

                    {activeTab === "Headers" && (
                        <div className={styles.tabPanel}>
                            <div className={styles.dataCard}>
                                <div className={styles.tableHeaderRow} style={{ gridTemplateColumns: constants.TABLE_COLUMNS }}>
                                    <div className={styles.tableHeaderCell}>On</div>
                                    <div className={styles.tableHeaderCell}>Key</div>
                                    <div className={styles.tableHeaderCell}>Value</div>
                                    <div className={styles.tableHeaderCell}>Description</div>
                                    <div className={styles.tableHeaderCell} />
                                </div>

                                <div className={styles.tableBody}>
                                    {headerRows.map((row, rowIndex) => (
                                        <div key={`header-${rowIndex}`} className={styles.tableDataRow} style={{ gridTemplateColumns: constants.TABLE_COLUMNS }}>
                                            <div className={styles.tableCellPad}>
                                                <input
                                                    type="checkbox"
                                                    checked={row.enabled}
                                                    onChange={(e) => updateRow(setHeaderRows, rowIndex, "enabled", e.target.checked)}
                                                />
                                            </div>
                                            <input
                                                value={row.key}
                                                onChange={(e) => updateRow(setHeaderRows, rowIndex, "key", e.target.value)}
                                                className={styles.tableInput}
                                            />
                                            <input
                                                value={row.value}
                                                onChange={(e) => updateRow(setHeaderRows, rowIndex, "value", e.target.value)}
                                                className={styles.tableInput}
                                            />
                                            <input
                                                value={row.description}
                                                onChange={(e) => updateRow(setHeaderRows, rowIndex, "description", e.target.value)}
                                                className={styles.tableInput}
                                            />
                                            <button
                                                type="button"
                                                onClick={() => removeRow(setHeaderRows, rowIndex)}
                                                className={styles.iconBtn}
                                            >
                                                x
                                            </button>
                                        </div>
                                    ))}
                                </div>

                                <button
                                    type="button"
                                    onClick={() => addRow(setHeaderRows)}
                                    className={styles.addRowBtn}
                                >
                                    + Add Header
                                </button>
                            </div>
                        </div>
                    )}

                    {activeTab === "Body" && (
                        <div className={styles.textareaWrap}>
                            <textarea
                                value={bodyInput}
                                onChange={(e) => setBodyInput(e.target.value)}
                                onBlur={() => setBodyInput((prev) => util.formatJsonIfPossible(prev))}
                                disabled={!canSendBody}
                                className={`${styles.textarea} ${canSendBody ? styles.textareaEnabled : styles.textareaDisabled}`}
                            />
                        </div>
                    )}

                    {activeTab === "cURL" && (
                        <div className={styles.curlWrap}>
                            <div className={styles.curlRelative}>
                                <button
                                    type="button"
                                    onClick={onCopyCurlClick}
                                    className={styles.copyBtn}
                                    aria-label="Copy cURL"
                                    title="Copy cURL"
                                >
                                    <img src="/assets/copy.svg" alt="" width="16" height="16" aria-hidden="true" />
                                </button>
                                {copyMessage && (
                                    <span className={styles.copyMessage}>
                                        {copyMessage}
                                    </span>
                                )}

                                <textarea
                                    value={curlCommand}
                                    readOnly
                                    className={`${styles.textarea} ${styles.textareaReadOnly}`}
                                />
                            </div>
                        </div>
                    )}

                    {activeTab === "Import cURL" && (
                        <div className={styles.importPanel}>
                            <textarea
                                value={importCurlText}
                                onChange={(e) => setImportCurlText(e.target.value)}
                                placeholder="Paste cURL here..."
                                className={`${styles.textarea} ${styles.textareaEnabled}`}
                            />

                            <div className={styles.importActions}>
                                <button
                                    type="button"
                                    onClick={onImportCurlClick}
                                    className={styles.primaryBtn}
                                >
                                    Import to Request
                                </button>

                                <span className={styles.importStatus}>{importMessage}</span>
                            </div>
                        </div>
                    )}

                    <div className={styles.responseSection}>
                        <div className={styles.responseTitle}>Response</div>
                        <textarea
                            value={responsePreview}
                            readOnly
                            className={styles.responseText}
                        />
                    </div>
                </section>
            </div>
        </main>
    );
}